return [{json: {filter: {filters: [{columnName: 'run_id', condition: 'eq', value: s.issue.run_id}]}, data: row, returnData: true, state: s}}];

const s = $json;
return [{json: {artifact: {contract: 'autodev.decision.v1', version: 'v1',
  run_id: s.issue.run_id, decision: 'BLOCKED',
